#!/usr/bin/env python3
"""Fresh-process production importer proof, with loaded-code fingerprint binding."""
import hashlib,json,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];OUT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'pipeline'));import ingest
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def eid(sid,pn,loc,code=None):return f'ca:{sid}:'+hashlib.sha256(f'{sid}|{pn}|{loc}|{code or "uncoded"}|occurrence:0'.encode()).hexdigest()[:20]
def main():
 sources=[s for s in json.loads((ROOT/'data/manifests/bncc-southeast.json').read_text())if re.search(r'^es-curr-culo-es-.*-vol-0[2-9]-',s['id'])];expected=set();rows=[];extracts={};hyp=[];sidecar_before={};source_before={};loaded=ingest.LOADED_PARSER_FINGERPRINT;before={p.name:sha(p)for p in(ROOT/'pipeline').glob('*.py')}
 for a in json.loads((OUT/'competence-field-denominator.json').read_text())['positive_anchors']:expected.add(eid(a['source_id'],a['page'],a['source_locator'],a['code']))
 expected.update(n['expected_id']for n in json.loads((OUT/'structural-denominator.json').read_text())['nodes'])
 for s in json.loads((OUT/'prose/physical-prose-inventory.json').read_text())['sections']:expected.add(s['expected_node_id']);expected.update(r['expected_id']for r in s['physical_items'])
 for s in sources:
  vol=int(re.search('-vol-0([2-9])-',s['id']).group(1));p=ROOT/f'data/manifests/uncoded/es-ef-competencies-vol{vol:02}.json';sidecar_before[str(p.relative_to(ROOT))]=sha(p);source_before[s['id']]=sha(ROOT/s['local_path']);assert source_before[s['id']]==s['sha256'];rows.extend(json.loads(p.read_text())['items']);inv=json.loads((OUT/'inventory'/f'{s["sha256"][:16]}.json').read_text());extracts[s['id']]={'source_id':s['id'],'sha256':s['sha256'],'pages':[{'page':x['page'],'text':'\n'.join(l['text']for l in x['lines'])}for x in inv['pages']]};hyp.append({**s,'uncoded_items_path':str(p.relative_to(ROOT))})
 errors=[];actual=ingest.source_uncoded_items(hyp,extracts,validation_errors=errors);final=ingest.finalize_items(actual,hyp);ids={r['id']for r in final};by={(r['source_id'],r['evidence'][0]['page'],r['evidence'][0]['locator']):r for r in final};identity=[]
 for r in rows:
  f=by.get((r['source_id'],r['page'],r['locator']));identity.append({'source_id':r['source_id'],'page':r['page'],'locator':r['locator'],'unchanged':bool(f)and all(f.get(k)==r.get(k)for k in('code','text','kind','positions'))})
 keys={(r['source_id'],r['key'])for r in rows if r.get('key')};parents=all(not r.get('parent_key')or(r['source_id'],r['parent_key'])in keys for r in rows);after={p.name:sha(p)for p in(ROOT/'pipeline').glob('*.py')};loaded_matches=all(before.get(name)==value for name,value in loaded['files'].items());source_after={s['id']:sha(ROOT/s['local_path'])for s in sources};sidecar_after={p:sha(ROOT/p)for p in sidecar_before};report={'actor_type':'automated','actor_id':'es-ef-competencies:fresh-production-importer-proof','expected_count':len(expected),'actual_count':len(ids),'expected_ids':sorted(expected),'actual_ids':sorted(ids),'missing':sorted(expected-ids),'extra':sorted(ids-expected),'errors':errors,'identity_checks':identity,'identity_failures':sum(not x['unchanged']for x in identity),'all_parents_resolve':parents,'loaded_parser_fingerprint':loaded,'loaded_fingerprint_matches_current_files':loaded_matches,'pipeline_files_before':before,'pipeline_files_after':after,'pipeline_stable':before==after,'source_sha256':source_before,'source_bytes_unchanged':source_before==source_after,'sidecar_sha256':sidecar_before,'sidecars_unchanged':sidecar_before==sidecar_after,'production_extraction_cache_read':False,'production_extraction_cache_written':False,'human_review':False};report['passed']=expected==ids and not errors and not report['identity_failures']and parents and loaded_matches and before==after and source_before==source_after and sidecar_before==sidecar_after;(OUT/'importer-final-verification.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print({k:report[k]for k in('passed','expected_count','actual_count','identity_failures','loaded_fingerprint_matches_current_files')})
if __name__=='__main__':main()
